  "strengths": [
    {
      "anchors": [
        {
          "utterance_index": 10,
          "quote": "Если люди пили воду из ближайшей колонки, версия Сноу трещит."
        },
        {
          "utterance_index": 12,
          "quote": "Совпадение сильное, но не стопроцентное, и Сноу его таким не выдаёт."
